import boto3

def normalize_expense(expense_fields):
    comprehend = boto3.client('comprehend')
    normalized_expense = {}
    for field, value in expense_fields.items():
        if field == 'vendor':
            normalized_expense['vendor'] = comprehend.detect_entities(Text=value, LanguageCode='en')
        elif field == 'date':
            normalized_expense['date'] = comprehend.detect_syntax(Text=value, LanguageCode='en')
        elif field == 'total':
            normalized_expense['total'] = comprehend.detect_key_phrases(Text=value, LanguageCode='en')
        else:
            normalized_expense[field] = value
    return normalized_expense

import boto3

def extract_receipt_fields(receipt_image):
    textract_client = boto3.client('textract')
    response = textract_client.analyze_document(
        Document={'Bytes': receipt_image},
        FeatureTypes=['FORMS']
    )

    merchant = None
    tax = None
    total = None
    items = []

    for block in response['Blocks']:
        if block['BlockType'] == 'KEY_VALUE_SET':
            if 'Merchant' in block['Text']:
                merchant = block['Text'].replace('Merchant', '').strip()
            elif 'Tax' in block['Text']:
                tax = block['Text'].replace('Tax', '').strip()
            elif 'Total' in block['Text']:
                total = block['Text'].replace('Total', '').strip()
        elif block['BlockType'] == 'LINE':
            items.append(block['Text'].strip())

    return {
        'merchant': merchant,
        'tax': tax,
        'total': total,
        'items': items
    }

import boto3

def extract_invoice_fields(document_path):
    client = boto3.client('textract')
    with open(document_path, 'rb') as document:
        imageBytes = document.read()
    response = client.analyze_document(
        Document={'Bytes': imageBytes},
        FeatureTypes=['FORMS'])
    vendor = None
    date = None
    total = None
    line_items = []
    for block in response['Blocks']:
        if block['BlockType'] == 'KEY_VALUE_SET':
            if 'VENDOR' in block['Text']:
                vendor = block['Text'].replace('VENDOR', '').strip()
            elif 'DATE' in block['Text']:
                date = block['Text'].replace('DATE', '').strip()
            elif 'TOTAL' in block['Text']:
                total = block['Text'].replace('TOTAL', '').strip()
        elif block['BlockType'] == 'LINE':
            line_items.append(block['Text'].strip())
    return {
        'vendor': vendor,
        'date': date,
        'total': total,
        'line_items': line_items
    }
